NOMINATE=r"""seed=>{state=clone(seed);const a=save,b=render,c=scrollTopNow;save=()=>{};render=()=>{};scrollTopNow=()=>{};try{for(const target of ['m4_227_dragon_council','m4_227_dragon_terms','m4_227_dragon_roll','m4_227_nominate_hansheng','m4_227_dragon_reply','m4_227_dragon_roll','m4_227_dragon_close','ch12_c62_02_frontier_227']){const sc=SCENES[state.scene];state.pageIndex=paginateStory(sc.body(state)).length-1;choose(sc.choices(state).findIndex(o=>o.next===target));if(sc.id===state.scene)throw Error('Nomination seed '+sc.id+':'+banner);}return clone(state);}finally{save=a;render=b;scrollTopNow=c;}}"""
